lemma IsIntertwining.comp {R : ProbabilisticTheory} {τ : G →* Reversible R R}
    {Φ : Channel P Q} {Ψ : Channel Q R} (hΦ : Φ.IsIntertwining ρ σ)
    (hΨ : Ψ.IsIntertwining σ τ) : (Ψ.comp Φ).IsIntertwining ρ τ

lemma exists_incl_eq_of_toQuasilocal_eq {i j : R} {a : (A i).Observables} {b : (A j).Observables}
    (h : toQuasilocal N i a = toQuasilocal N j b) :
    ∃ (k : R) (hik : i ≤ k) (hjk : j ≤ k), N.incl hik a = N.incl hjk b

lemma sumIn_count_tsum [Countable ι] {Λ : R}
    (h : Integrable (Φ.termIn Λ) Measure.count) :
    Φ.sumIn Measure.count Λ = ∑' i, Φ.termIn Λ i

lemma add_mem_pos {x y : N.Quasilocal}
    (hx : x ∈ positive N) (hy : y ∈ positive N) :
    x + y ∈ positive N

lemma IsInvariant.comap {ρ : G →* Reversible P P} {σ : G →* Reversible Q Q}
    {Φ : Channel P Q} {ω : Q.State} (hω : ω.IsInvariant σ)
    (h : Φ.IsIntertwining ρ σ) : (ω.comap Φ).IsInvariant ρ
